34	function requireEnv(name: string): string {
35	  const value = process.env[name];
36	  if (value === undefined || value === "") {
37	    throw new Error(
38	      `${name} is not set on the Convex deployment. Run: npx convex env set ${name} <value>`,
39	    );
40	  }
41	  return value;
42	}
