44	// Haven's platform names are used everywhere else in the app ("x" on the
45	// card, in profileFields.ts). Composio's toolkit slug for that platform is
46	// still "twitter" -- the only place the two vocabularies have to meet.
47	const PLATFORMS = ["linkedin", "instagram", "x"] as const;
48	export type SocialPlatform = (typeof PLATFORMS)[number];
49	
50	const TOOLKIT_SLUG: Record<SocialPlatform, string> = {
51	  linkedin: "linkedin",
52	  instagram: "instagram",
53	  x: "twitter",
54	};
55	
56	// The one tool per toolkit that answers "who is this account", proven live
57	// against each platform (see the file header for LinkedIn and Instagram).
58	// X's exact response shape is inferred from the standard Twitter API v2
59	// users/me payload, which Composio's tool wraps -- worth confirming against
60	// a live connection before this ships, the way LinkedIn and Instagram
61	// already were.
62	const PROFILE_TOOL: Record<SocialPlatform, string> = {
63	  linkedin: "LINKEDIN_GET_MY_INFO",
64	  instagram: "INSTAGRAM_GET_USER_INFO",
65	  x: "TWITTER_USER_LOOKUP_ME",
66	};
67	
68	// Extra arguments a platform's profile tool needs to hand back its photo.
69	// LinkedIn and Instagram include theirs by default; X's underlying API v2
70	// only returns profile_image_url when user.fields asks for it. Composio
71	// tools pass arguments through to the wrapped API mostly verbatim, so
72	// "user_fields" here is inferred from that convention, the same caveat
73	// PROFILE_TOOL.x already carries -- not live-proven, and this call is made
74	// the same way whether the field comes back or not.
75	const TOOL_ARGUMENTS: Partial<Record<SocialPlatform, Record<string, unknown>>> = {
76	  x: { user_fields: "profile_image_url" },
77	};
