86	
87	async function composioRequest(
88	  path: string,
89	  init: RequestInit = {},
90	): Promise<Response> {
91	  const apiKey = requireEnv("COMPOSIO_API_KEY");
92	  return fetch(`${BASE_URL}${path}`, {
93	    ...init,
94	    headers: {
95	      "Content-Type": "application/json",
96	      "x-api-key": apiKey,
97	      ...(init.headers ?? {}),
98	    },
99	  });
100	}
101	
102	// A failure body this gets truncated before it ever reaches a thrown Error:
103	// Convex logs and error-tracking both keep the message whole, and an upstream
104	// error page or a misbehaving proxy can hand back megabytes of HTML for what
105	// is, to every caller here, the same "this call failed" outcome.
106	const MAX_ERROR_DETAIL_LENGTH = 500;
107	
108	async function composioJson<T>(
109	  path: string,
110	  init: RequestInit = {},
111	): Promise<T> {
112	  const response = await composioRequest(path, init);
113	  if (!response.ok) {
114	    const detail = await response.text();
115	    const truncated =
116	      detail.length > MAX_ERROR_DETAIL_LENGTH
117	        ? `${detail.slice(0, MAX_ERROR_DETAIL_LENGTH)}...`
118	        : detail;
119	    throw new Error(`Composio ${path} failed (${response.status}): ${truncated}`);
120	  }
121	  return (await response.json()) as T;
122	}
