134	export const getCachedAuthConfigId = internalQuery({
135	  args: { toolkit: v.string() },
136	  returns: v.union(v.string(), v.null()),
137	  handler: async (ctx, args) => {
138	    const rows = await ctx.db
139	      .query("composioAuthConfigs")
140	      .withIndex("by_toolkit", (q) => q.eq("toolkit", args.toolkit))
141	      .take(1);
142	    return rows[0]?.authConfigId ?? null;
143	  },
