146	// Check-then-insert inside one mutation, same as every other idempotent
147	// creation in this codebase: Convex runs mutations transactionally, so two
148	// concurrent ensureAuthConfig calls for a toolkit neither has cached yet
149	// cannot both win the insert, even though both may reach here.
150	export const cacheAuthConfigId = internalMutation({
151	  args: { toolkit: v.string(), authConfigId: v.string() },
152	  returns: v.null(),
153	  handler: async (ctx, args) => {
154	    const rows = await ctx.db
155	      .query("composioAuthConfigs")
156	      .withIndex("by_toolkit", (q) => q.eq("toolkit", args.toolkit))
157	      .take(1);
158	    if (rows.length > 0) {
159	      return null;
160	    }
161	    await ctx.db.insert("composioAuthConfigs", args);
162	    return null;
163	  },
164	});
