166	// The auth config is Composio's OAuth app registration for a toolkit --
167	// created once, ever, and reused by every connection to that toolkit. Three
168	// places are checked in order, cheapest first: our own cache, then
169	// Composio's own list (in case one already exists from the dashboard, or a
170	// deploy that raced this one), and only then a create. A local cache miss
171	// racing another request's create is a narrow, low-stakes window -- worst
172	// case Composio ends up with two auth configs for one toolkit, not a broken
173	// connection -- so this does not try to lock across the network call.
174	async function ensureAuthConfig(
175	  ctx: ActionCtx,
176	  platform: SocialPlatform,
177	): Promise<string> {
178	  const toolkit = TOOLKIT_SLUG[platform];
179	  const cached: string | null = await ctx.runQuery(
180	    internal.composio.getCachedAuthConfigId,
181	    { toolkit },
182	  );
183	  if (cached !== null) {
184	    return cached;
185	  }
186	
187	  const listed = await composioJson<AuthConfigListResponse>(
188	    `/auth_configs?toolkit_slug=${encodeURIComponent(toolkit)}`,
189	  );
190	  const existing = listed.items.find((item) => item.toolkit.slug === toolkit);
191	  const authConfigId =
192	    existing?.id ??
193	    (
194	      await composioJson<AuthConfigCreateResponse>("/auth_configs", {
195	        method: "POST",
196	        body: JSON.stringify({
197	          toolkit: { slug: toolkit },
198	          auth_config: {
199	            type: "use_composio_managed_auth",
200	            name: `Haven ${toolkit}`,
201	          },
202	        }),
203	      })
204	    ).auth_config.id;
205	
206	  await ctx.runMutation(internal.composio.cacheAuthConfigId, {
207	    toolkit,
208	    authConfigId,
209	  });
210	  return authConfigId;
211	}
