215	type ConnectedAccountStatus =
216	  | "INITIALIZING"
217	  | "INITIATED"
218	  | "ACTIVE"
219	  | "FAILED"
220	  | "EXPIRED"
221	  | "INACTIVE"
222	  | "REVOKED";
