243	// A personal Instagram account, not creator/business, is Composio's
244	// documented limit on this toolkit: the profile tool fails with Meta's own
245	// OAuthException (code 190 / an HTTP 403 shape), not a Composio-specific
246	// error. Matched on the message text, which is what a tool-execute failure
247	// actually gives us -- `error` is a plain string, not a structured code.
248	function isUnsupportedInstagramAccount(errorMessage: string): boolean {
249	  const message = errorMessage.toLowerCase();
250	  return (
251	    message.includes("oauthexception") ||
252	    message.includes("(#190)") ||
253	    message.includes("business and creator") ||
254	    message.includes("business or creator")
255	  );
256	}
