258	// The one field on each platform's profile tool that is the handle, per the
259	// live-proven shapes in the file header. X's nesting is defensive: Composio
260	// tools sometimes flatten the upstream response and sometimes pass it
261	// through, so both `username` and a nested `data.username` are checked.
262	function extractHandle(
263	  platform: SocialPlatform,
264	  data: Record<string, unknown>,
265	): string | null {
266	  const read = (key: string): string | null => {
267	    const value = data[key];
268	    return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
269	  };
270	  if (platform === "linkedin") {
271	    return read("vanityName");
272	  }
273	  if (platform === "instagram") {
274	    return read("username");
275	  }
276	  const direct = read("username");
277	  if (direct !== null) {
278	    return direct;
279	  }
280	  const nested = data["data"];
281	  if (nested !== null && typeof nested === "object") {
282	    const nestedUsername = (nested as Record<string, unknown>)["username"];
283	    if (typeof nestedUsername === "string" && nestedUsername.trim() !== "") {
284	      return nestedUsername.trim();
285	    }
286	  }
287	  return null;
288	}
