290	// The one field on each platform's profile tool that is a photo, per the
291	// same live-proven shapes: LinkedIn nests it under profilePicture, Instagram
292	// has it flat. Optional everywhere -- a profile with no photo, or a platform
293	// that did not hand one back this call, must not fail the connection over
294	// it, so this returns null rather than throwing either way.
295	function extractPhotoUrl(
296	  platform: SocialPlatform,
297	  data: Record<string, unknown>,
298	): string | null {
299	  const read = (key: string): string | null => {
300	    const value = data[key];
301	    return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
302	  };
303	  if (platform === "linkedin") {
304	    const picture = data["profilePicture"];
305	    if (picture === null || typeof picture !== "object") {
306	      return null;
307	    }
308	    const displayImage = (picture as Record<string, unknown>)["displayImage"];
309	    return typeof displayImage === "string" && displayImage.trim() !== ""
310	      ? displayImage.trim()
311	      : null;
312	  }
313	  if (platform === "instagram") {
314	    return read("profile_picture_url");
315	  }
316	  // See TOOL_ARGUMENTS.x: only present when user.fields asked for it, and
317	  // never proven live, so this is the one platform where absent is expected
318	  // rather than merely tolerated.
319	  return read("profile_image_url");
320	}
321	
322	// Runs the platform's profile tool over an ACTIVE connection and, on
323	// success, stores the handle it proves. Shared by completeSocialConnection's
324	// ACTIVE branch and initiateSocialConnection's dedupe branch, so "what a
325	// connection resolves to" is answered the same way regardless of which path
326	// found it ACTIVE.
327	async function resolveAndStoreHandle(
328	  ctx: ActionCtx,
329	  platform: SocialPlatform,
330	  connectedAccountId: string,
331	  userId: string,
332	): Promise<
333	  | { status: "connected"; handle: string; photoUrl?: string }
334	  | { status: "unsupported_account" }
335	  | { status: "failed" }
336	> {
337	  const toolArguments = TOOL_ARGUMENTS[platform];
338	  const result = await composioJson<ToolExecuteResponse>(
339	    `/tools/execute/${PROFILE_TOOL[platform]}`,
340	    {
341	      method: "POST",
342	      body: JSON.stringify({
343	        connected_account_id: connectedAccountId,
344	        user_id: userId,
345	        ...(toolArguments ? { arguments: toolArguments } : {}),
346	      }),
347	    },
348	  );
349	
350	  if (!result.successful) {
351	    if (platform === "instagram" && isUnsupportedInstagramAccount(result.error ?? "")) {
352	      return { status: "unsupported_account" };
353	    }
354	    return { status: "failed" };
355	  }
356	
357	  const handle = extractHandle(platform, result.data);
358	  if (handle === null) {
359	    return { status: "failed" };
360	  }
361	
362	  await storeVerifiedHandle(ctx, platform, handle);
363	  const photoUrl = extractPhotoUrl(platform, result.data);
364	  return { status: "connected", handle, photoUrl: photoUrl ?? undefined };
365	}
366	
367	// Merges the newly proven handle into the card's existing handles rather
368	// than replacing the array: updateMyProfile's `handles` argument is the
369	// whole list, and a person who already connected one platform must not lose
370	// it when a second one lands. Idempotent by construction -- the filter
371	// always drops this platform's old entry first, so storing the same handle
372	// twice produces the same array both times, not a duplicate.
373	async function storeVerifiedHandle(
374	  ctx: ActionCtx,
375	  platform: SocialPlatform,
376	  handle: string,
377	): Promise<void> {
378	  const card = await ctx.runQuery(api.profiles.getMyCard, {});
379	  const existingHandles = card?.handles ?? [];
380	  const nextHandles = [
381	    ...existingHandles.filter((existing) => existing.platform !== platform),
382	    { platform, value: handle, verified: true },
383	  ];
384	  await ctx.runMutation(api.profiles.updateMyProfile, {
385	    handles: nextHandles,
386	    // The first platform anyone connects becomes what the card leads with;
387	    // reconnecting an already-primary platform, or adding a second one,
388	    // leaves that choice alone.
389	    primaryPlatform: card?.primaryPlatform ?? platform,
390	  });
391	}
