395	export const initiateSocialConnection = action({
396	  args: { platform: platformValidator },
397	  returns: v.union(
398	    v.object({
399	      status: v.literal("redirect"),
400	      redirectUrl: v.string(),
401	      connectedAccountId: v.string(),
402	    }),
403	    v.object({ status: v.literal("already"), handle: v.string() }),
404	    v.object({ status: v.literal("unsupported_account") }),
405	    v.object({ status: v.literal("failed") }),
406	  ),
407	  handler: async (ctx, args) => {
408	    const userId = await requireUser(ctx);
409	    // Every branch below makes at least one metered Composio call (a list,
410	    // sometimes also a tool execution or a link creation), the same
411	    // denial-of-wallet threat model rateLimit.ts exists for. This is a
412	    // rarely repeated, user-initiated tap, not a poll, so the cap is tight.
413	    await ctx.runMutation(internal.people.enforceRateLimit, {
414	      userId,
415	      action: "initiateSocialConnection",
416	      max: 10,
417	      windowMs: MINUTE_MS,
418	    });
419	    const toolkit = TOOLKIT_SLUG[args.platform];
420	
421	    // One account per toolkit per user: Composio's own list is the source of
422	    // truth for this, not a local mirror that could drift from it.
423	    const existing = await composioJson<ConnectedAccountListResponse>(
424	      `/connected_accounts?user_ids[]=${encodeURIComponent(userId)}&toolkit_slugs[]=${toolkit}&statuses[]=ACTIVE`,
425	    );
426	    // Found by toolkit, not taken on faith as items[0]: the query params are
427	    // a request, not a guarantee, and a filter Composio silently ignored
428	    // would otherwise resolve and store a handle from the wrong toolkit.
429	    const match = existing.items.find((item) => item.toolkit.slug === toolkit);
430	    if (match !== undefined) {
431	      const outcome = await resolveAndStoreHandle(
432	        ctx,
433	        args.platform,
434	        match.id,
435	        userId,
436	      );
437	      if (outcome.status === "connected") {
438	        return { status: "already" as const, handle: outcome.handle };
439	      }
440	      return outcome;
441	    }
442	
443	    const authConfigId = await ensureAuthConfig(ctx, args.platform);
444	    const link = await composioJson<LinkResponse>("/connected_accounts/link", {
445	      method: "POST",
446	      body: JSON.stringify({ auth_config_id: authConfigId, user_id: userId }),
447	    });
448	    return {
449	      status: "redirect" as const,
450	      redirectUrl: link.redirect_url,
451	      connectedAccountId: link.connected_account_id,
452	    };
453	  },
454	});
