456	export const completeSocialConnection = action({
457	  args: { platform: platformValidator, connectedAccountId: v.string() },
458	  returns: v.union(
459	    v.object({ status: v.literal("pending") }),
460	    v.object({
461	      status: v.literal("connected"),
462	      handle: v.string(),
463	      photoUrl: v.optional(v.string()),
464	    }),
465	    v.object({ status: v.literal("unsupported_account") }),
466	    v.object({ status: v.literal("failed") }),
467	  ),
468	  handler: async (ctx, args) => {
469	    const userId = await requireUser(ctx);
470	    // The iOS client polls this every 2s for up to 120s while a browser
471	    // sheet is open -- roughly 30 calls a minute of genuine use, each one a
472	    // metered Composio list call and sometimes also a tool execution. 40
473	    // comfortably covers one real polling loop with room for a client that
474	    // starts a little early or a request that lands right at a window
475	    // boundary, while still bounding the same denial-of-wallet threat every
476	    // other metered action in this codebase is capped against.
477	    await ctx.runMutation(internal.people.enforceRateLimit, {
478	      userId,
479	      action: "completeSocialConnection",
480	      max: 40,
481	      windowMs: MINUTE_MS,
482	    });
483	
484	    // A connected account id is not a secret the caller minted -- it came
485	    // back from initiateSocialConnection to whoever asked, and ids are not
486	    // guaranteed unguessable. Without an authoritative ownership check,
487	    // polling somebody else's id would write their proven handle onto the
488	    // caller's own card as "verified".
489	    //
490	    // This has to be independent of connected_accounts.user_id: Composio's
491	    // own OpenAPI spec documents that field as being removed entirely ("we
492	    // will not be providing userId from this api anymore") and some
493	    // responses already omit it, so a check that only compared it when
494	    // present treated its absence as "nothing to check against, so allow" --
495	    // which is not a narrower guard, it is no guard at all the moment the
496	    // field is missing. Listing the caller's own connected accounts is the
497	    // same call initiateSocialConnection already trusts to answer "does this
498	    // user already have one"; requiring the id to appear in that list is
499	    // authoritative because the list itself is server-scoped to `userId`,
500	    // not because of anything the target account's own record claims about
501	    // itself.
502	    const owned = await composioJson<ConnectedAccountListResponse>(
503	      `/connected_accounts?user_ids[]=${encodeURIComponent(userId)}`,
504	    );
505	    const account = owned.items.find((item) => item.id === args.connectedAccountId);
506	    if (account === undefined) {
507	      return { status: "failed" as const };
508	    }
509	    if (account.toolkit.slug !== TOOLKIT_SLUG[args.platform]) {
510	      return { status: "failed" as const };
511	    }
512	
513	    if (account.status === "INITIALIZING" || account.status === "INITIATED") {
514	      return { status: "pending" as const };
515	    }
516	    if (account.status !== "ACTIVE") {
517	      // FAILED, EXPIRED, INACTIVE, REVOKED: none of these will ever become
518	      // ACTIVE on their own, so all four are the same "give up" answer to
519	      // the client polling this.
520	      return { status: "failed" as const };
521	    }
522	
523	    return await resolveAndStoreHandle(
524	      ctx,
525	      args.platform,
526	      args.connectedAccountId,
527	      userId,
528	    );
529	  },
530	});
