532	// --------------------------------------------------------- account deletion
533	
534	type ConnectedAccountDeleteResponse = {
535	  success: boolean;
536	  revoke_job_id?: string;
537	};
538	
539	// Scheduled from profiles.deleteMyAccount rather than called inline: that is
540	// a mutation, and mutations cannot reach the network. Composio has no idea a
541	// Convex account was just deleted, and a connected account left alone keeps
542	// its OAuth tokens alive at Composio under a userId nothing on Haven's side
543	// will ever look up again.
544	//
545	// `revoke_on_delete=true` is load bearing, not a default worth accepting:
546	// without it, DELETE only soft-deletes the record (Composio's own
547	// description -- "marking it as deleted... prevents the account from being
548	// used for API calls but preserves the record") and leaves the upstream
549	// OAuth credentials live. Revocation runs as Composio's own background job,
550	// so this does not wait on it -- there is no programmatic way to poll it yet
551	// per the OpenAPI spec, and nothing here needs to.
552	//
553	// Every failure is caught and logged, never rethrown: deleteMyAccount has
554	// already committed by the time this runs (see its own comment on why),
555	// and a Composio outage -- no network, a missing COMPOSIO_API_KEY, a 500 --
556	// must never read as the account deletion having failed. What is left
557	// behind at worst is a connected account nothing here will ever reference
558	// again, not a person whose deletion silently did not happen.
559	export const deleteConnectedAccountsForUser = internalAction({
560	  args: { userId: v.string() },
561	  returns: v.null(),
562	  handler: async (ctx, args) => {
563	    // Distinct from every failure below: a deployment that has never
564	    // configured Composio (a preview environment, a fresh clone) is not
565	    // failing to reach it, it never intended to reach it at all, and logging
566	    // that as a cleanup failure on every single account deletion would be
567	    // permanent, uninformative noise in exactly the deployments where nobody
568	    // can act on it.
569	    if (process.env.COMPOSIO_API_KEY === undefined || process.env.COMPOSIO_API_KEY === "") {
570	      return null;
571	    }
572	
573	    let accounts: ConnectedAccountListResponse;
574	    try {
575	      // No `statuses` filter: an EXPIRED or INACTIVE connection still holds
576	      // whatever token it last had, and the point of this pass is to reach
577	      // every one of them, not only the ones still ACTIVE.
578	      accounts = await composioJson<ConnectedAccountListResponse>(
579	        `/connected_accounts?user_ids[]=${encodeURIComponent(args.userId)}`,
580	      );
581	    } catch (error) {
582	      console.error(
583	        `Composio cleanup: could not list connected accounts for ${args.userId}`,
584	        error,
585	      );
586	      return null;
587	    }
588	
589	    for (const account of accounts.items) {
590	      try {
591	        await composioJson<ConnectedAccountDeleteResponse>(
592	          `/connected_accounts/${account.id}?revoke_on_delete=true`,
